import type { ProjectDocumentPreviewSection, ProjectFileKind } from '@bezier/contracts';
import type { useT } from '../i18n';

/** Only these document/presentation section labels are generated by our preview
 * service. Spreadsheet sheet names and extracted document text are user content. */
export function documentPreviewSectionTitle(
  fileKind: ProjectFileKind,
  title: string,
  index: number,
  t: ReturnType<typeof useT>,
  metadata?: Pick<ProjectDocumentPreviewSection, 'notice' | 'generatedTitle'>,
): string {
  if (fileKind === 'spreadsheet') {
    if (metadata?.generatedTitle === 'sheet') return t('fileViewer.sheetTitle', { number: index + 1 });
    if (metadata?.notice === 'no-readable-sheets' && title === 'Spreadsheet') return t('fileViewer.spreadsheetMeta');
  }
  if (fileKind === 'document' && index === 0 && title === 'Document') return t('fileViewer.documentMeta');
  if (fileKind === 'presentation') {
    if (title === `Slide ${index + 1}`) return t('fileViewer.slideTitle', { number: index + 1 });
    if (index === 0 && title === 'Presentation') return t('fileViewer.presentationMeta');
  }
  return title;
}

const NOTICE_KEYS = {
  'no-readable-text': 'fileViewer.notice.no-readable-text',
  'no-readable-slides': 'fileViewer.notice.no-readable-slides',
  'no-readable-sheets': 'fileViewer.notice.no-readable-sheets',
  'no-readable-cells': 'fileViewer.notice.no-readable-cells',
  'pdf-unavailable': 'fileViewer.notice.pdf-unavailable',
} as const;

/** Never guess that an extracted line is a status based on its wording. */
export function documentPreviewSectionLines(section: ProjectDocumentPreviewSection, t: ReturnType<typeof useT>): string[] {
  const key = section.notice && NOTICE_KEYS[section.notice];
  return key ? [t(key)] : section.lines;
}
